const envelope = $input.first().json;
const persisted = envelope.persisted_state;
if (!persisted?.state_id || !persisted?.snapshot) throw new Error('Assessor aceita somente Estado 360 persistido');
const state = persisted.snapshot;
const findings = state.findings ?? [];
const gaps = state.data_gaps ?? [];
const actions = state.recommended_actions ?? [];
const summary = state.overall_status === 'READY' ? `Estado 360 pronto com ${findings.length} achado(s), ${gaps.length} lacuna(s) declarada(s) e ${actions.length} ação(ões) proposta(s).` : `Estado 360 requer revisão manual. Há ${findings.length} achado(s) e ${gaps.length} lacuna(s) registradas.`;
const assessment = { schema_version: '1.0.0', state_id: persisted.state_id, state_version: persisted.state_version, state_hash: persisted.state_hash, generated_at: new Date().toISOString(), overall_status: state.overall_status, summary, key_findings: findings.map(({ finding_id, topic, statement, evidence_quality, risk_level }) => ({ finding_id, topic, statement, evidence_quality, risk_level })), blind_spots: gaps.map(({ field, reason_code, impact, remediation }) => ({ field, reason_code, impact, remediation })), next_actions: actions.map(({ action_id, action, priority, requires_human_approval, execution_authorization }) => ({ action_id, action, priority, requires_human_approval, execution_authorization })), manual_review: state.manual_review, source_constraint: 'PERSISTED_STATE_ONLY', external_effects_allowed: false };
return [{ json: { ...envelope, executive_assessment: assessment } }];
